-- SAF-04 Safety performance (step 3): safety performance indicators (SPI) and targets (SPT) per entity, as in ENR-CM-06,
-- linked to the safety objectives of the MSM; values computed from S.A.M. (reports, MOR, hazard log, assessments, actions)
-- or entered monthly by the safety desk (activity hours, surveys, promotion, operational counts kept outside S.A.M.).
-- A value entered for a month always wins over the computed one (history imported from the ENR-CM-06 workbooks).
create table if not exists spi_defs (
  id uuid primary key default gen_random_uuid(),
  entity entity_code not null references entities(code),
  code text not null,                          -- SPI-04 · S1
  label text not null,
  objective text,                              -- safety objective of the MSM it measures
  area text not null default 'other',          -- outcome · reporting · hazards · operational · promotion · management · culture · erp · other
  metric text,                                 -- computed by S.A.M. (lib/spi-shared METRICS); null = entered by hand
  basis text not null default 'count' check (basis in ('count','per_1000_bh','per_1000_fh','per_100_fh','per_1000_flights','percent','score')),
  direction text not null default 'le' check (direction in ('le','ge','eq')),
  period text not null default 'month' check (period in ('month','quarter','year')),  -- the period the target is set for
  agg text check (agg in ('sum','last','avg')), -- how months add up (default: sum; percent / score: pooled / mean)
  ref text, owner_role text, sort int not null default 0,
  status text not null default 'active' check (status in ('active','proposed','retired')),
  note text,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (entity, code)
);
create table if not exists spi_targets (
  spi_id uuid not null references spi_defs(id) on delete cascade,
  year int not null,
  target numeric,                              -- null = TBD / not applicable this year
  alert numeric,                               -- alert threshold (beyond it: far off target)
  note text,
  set_by uuid references people(id), set_at timestamptz not null default now(),
  primary key (spi_id, year)
);
create table if not exists spi_data (
  entity entity_code not null references entities(code),
  key text not null,                           -- bh · fh · flights · spi:<code>
  month date not null,                         -- first day of the month
  value numeric not null,
  den numeric,                                 -- for a percentage entered as "x of y"
  source text not null default 'manual',
  note text,
  entered_by uuid references people(id), entered_at timestamptz not null default now(),
  primary key (entity, key, month)
);
create table if not exists spi_notes (
  id uuid primary key default gen_random_uuid(),
  entity entity_code not null references entities(code),
  year int not null, quarter int,
  text text not null,
  model text,
  created_by uuid references people(id), created_at timestamptz not null default now()
);
alter table spi_defs enable row level security; alter table spi_targets enable row level security; alter table spi_data enable row level security; alter table spi_notes enable row level security;
create policy spi_defs_read on spi_defs for select to authenticated using (entity = any(my_entities()));
create policy spi_data_read on spi_data for select to authenticated using (entity = any(my_entities()));

-- an action can come from an SPI off target (ENR-CM-06: off target two months in a row → action)
alter table safety_actions add column if not exists spi_id uuid references spi_defs(id) on delete set null;
alter table safety_actions drop constraint if exists safety_actions_source_kind_check;
alter table safety_actions add constraint safety_actions_source_kind_check check (source_kind in ('report','hazard','assessment','committee','audit','finding','spi','other'));

-- SPI sets: ASJ = ENR-CM-06 2025 (SPT 2025 and 2026) · AJD = same set, proposed · ASF = ENR-CM-06 Ed1 Rev3 (safety part)
